```17:41:server/src/slots/slots.service.ts
  async getSlots(): Promise<ResourceSlotsDto[]> {
    // TODO: Implement this method.
    // Return today's slots grouped by resource, including slots from
    // blocking resources. Each slot should have its conflicts computed.
    const [resources, slots] = await Promise.all([
      this.manager.find(Resource, { order: { id: 'ASC' } }),
      this.manager.find(Slot, { order: { start: 'ASC', id: 'ASC' } }),
    ]);

    const slotsByResourceId = new Map<number, Slot[]>();

    for (const slot of slots) {
      const resourceSlots = slotsByResourceId.get(slot.resourceId) ?? [];
      resourceSlots.push(slot);
      slotsByResourceId.set(slot.resourceId, resourceSlots);
    }

    return resources.map((resource) => ({
      resourceId: resource.id,
      slots: (slotsByResourceId.get(resource.id) ?? []).map((slot) => ({
        ...slot,
        conflicts: [],
      })),
    }));
  }
```

How it works:

- **Two queries:** it loads resources and slots in two parallel queries. That's simpler than a separate query per resource.
- **Grouping:** one pass over the slots builds a `slotsByResourceId` map. This replaces the old `result.find(...)` lookup that ran for every slot.
- **Entries come from resources:** the result is built from the resource list, not the slot list, which is why Lane 4 now appears.
- **Ordering:** slots are sorted by start time, then id.

